CJava <pre><code>void selection_sort(int a[], int n, int *comparisons, int *swaps) {
    for (int i = 0; i &lt; n - 1; i++) {
        int min_idx = i;
        for (int j = i + 1; j &lt; n; j++) {
            (*comparisons)++;
            if (a[j] &lt; a[min_idx]) min_idx = j;
        }
        if (min_idx != i) {              /* skip the swap if i is already the minimum */
            int tmp = a[i];
            a[i] = a[min_idx];
            a[min_idx] = tmp;
            (*swaps)++;
        }
    }
}
