            while (i + z[i] &lt; n &amp;&amp; s.charAt(z[i]) == s.charAt(i + z[i]))
                z[i]++;                              // extend by direct comparison
            if (i + z[i] &gt; r) { l = i; r = i + z[i]; }   // window grew: remember it
