static int seqSearchFile(RandomAccessFile fp, int n, int key, int[] blockReads, int[] comparisons) throws IOException {
    int[] buf = new int[BF];
    int nblocks = (n + BF - 1) / BF;
    for (int b = 0; b &lt; nblocks; b++) {
        fp.seek((long) b * BF * 4);
        int cnt = 0;
