    while (fib &gt; 1) {
        int i = (offset + fib2 &lt; n - 1) ? offset + fib2 : n - 1;
        comp++;
        printf("  probe %d: i=%d arr[i]=%d (fib=%d fib1=%d fib2=%d offset=%d)\n",
