    int idx = h(key);
    Node *n = malloc(sizeof(Node));
    n-&gt;key = key;
    n-&gt;next = table[idx];              /* new node becomes the head: O(1) */
    table[idx] = n;
}

int search(int key, int *probes) {
    int idx = h(key);
    int p = 0;
    for (Node *cur = table[idx]; cur != NULL; cur = cur-&gt;next) {
        p++;
        if (cur-&gt;key == key) { *probes = p; return 1; }
    }
    *probes = p;
    return 0;
}

