            new EdgeIn("C", "F"), new EdgeIn("E", "G"), new EdgeIn("F", "G"), new EdgeIn("G", "H"), new EdgeIn("B", "E")
        };
        runScenario("edge: a cycle-free graph (a DAG), every vertex is its own component", dag);
    }
}
