        {"A", "B", 10}, {"A", "C", 8}, {"B", "C", 5}, {"B", "D", 5},
        {"C", "D", 3}, {"C", "E", 6}, {"D", "E", 2}, {"D", "F", 8},
        {"E", "F", 4}, {"E", "G", 6}, {"F", "H", 9}, {"G", "H", 7},
