                if (a[j].key &lt; a[minIdx].key) minIdx = j;
            if (minIdx != i) {
                Rec tmp = a[i]; a[i] = a[minIdx]; a[minIdx] = tmp;   // can jump a tie out of order
            }
        }
    }

    static Rec[] clone(Rec[] src) {
