        System.out.println("before:            " + recordsStr(src));

        Rec[] a1 = clone(src);
        insertionSortStable(a1);
        System.out.println("stable (insert):   " + recordsStr(a1));

        Rec[] a2 = clone(src);
        selectionSortUnstable(a2);
        System.out.println("unstable (select): " + recordsStr(a2));
        System.out.println();
    }

