    for (int i = 0; i &lt; n; i++) printf(" %d", sa[i]);
    printf("\n");
    for (int i = 0; i &lt; n; i++) printf("  sa[%d]=%d -&gt; \"%s\"\n", i, sa[i], text + sa[i]);
