public class LongestCommonSubsequence {
    static int lcsLength(String a, String b, int[][] dp) {
        int n = a.length(), m = b.length();
        for (int i = 0; i &lt;= n; i++) dp[i][0] = 0;
        for (int j = 0; j &lt;= m; j++) dp[0][j] = 0;
