        if (pages[page].overflow_tail == NULL)
            pages[page].overflow_head = node;
        else
            pages[page].overflow_tail-&gt;next = node;
        pages[page].overflow_tail = node;
        printf("insert(%d) -&gt; page %d is full: OVERFLOW\n", key, page + 1);
