        return -1;   // m probes tried: table full, OR (m not prime / alpha &gt; 0.5) the
                     // sequence cycled without ever reaching a free slot
    }

    static int occupiedCount() { int c = 0; for (int i = 0; i &lt; m; i++) if (state[i] == OCCUPIED) c++; return c; }
