            return;
        }
        AdjNode cur = g.adj[v];
        while (cur.next != null &amp;&amp; g.label[cur.next.to].compareTo(g.label[neighbour]) &lt;= 0)
            cur = cur.next;
        n.next = cur.next;
        cur.next = n;
    }

