        }
        AdjNode cur = g.adj[v];
        while (cur.next != null &amp;&amp; g.label[cur.next.to].compareTo(g.label[neighbour]) &lt;= 0) cur = cur.next;
        n.next = cur.next; cur.next = n;
    }

    static void buildGraph(Graph g, EdgeIn[] edges) {
        g.vertexCount = 0;
        for (int i = 0; i &lt; MAX_V; i++) g.adj[i] = null;
