        for (int v = t; v != s; v = parent_of[v]) {
            int u = parent_of[v];
            cap_of[u][v] -= bottleneck;                      /* use up forward capacity */
            cap_of[v][u] += bottleneck;                      /* open up backward (undo) capacity */
        }
        max_flow += bottleneck;
    }
    return max_flow;
}

static int find_or_add_vertex(const char *lbl) {
